import{_ as a,o,c as e,a2 as r}from"./chunks/framework.Bqa2y7hU.js";const p=JSON.parse('{"title":"我的机器人","description":"添加机器人、看懂列表、以及机器人详情页五个 Tab 各能做什么。","frontmatter":{"title":"我的机器人","description":"添加机器人、看懂列表、以及机器人详情页五个 Tab 各能做什么。"},"headers":[],"relativePath":"console/bots.md","filePath":"console/bots.md","lastUpdated":1789487229000}'),d={name:"console/bots.md"};function l(i,t,n,h,s,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="我的机器人-🤖" tabindex="-1">我的机器人 🤖 <a class="header-anchor" href="#我的机器人-🤖" aria-label="Permalink to &quot;我的机器人 🤖&quot;">​</a></h1><p>「我的机器人」是你管理机器人本体的地方：新增、查看状态、进详情页管插件、翻消息记录和日志。</p><p>这页按你实际的操作顺序讲：先怎么加，加完在列表里看到什么，点进去之后五个 Tab 分别能干什么。</p><h2 id="_1-添加机器人-两步向导" tabindex="-1">1. 添加机器人：两步向导 <a class="header-anchor" href="#_1-添加机器人-两步向导" aria-label="Permalink to &quot;1. 添加机器人：两步向导&quot;">​</a></h2><p>点右上角「添加机器人」，向导分两步。</p><h3 id="第-1-步-选平台" tabindex="-1">第 1 步：选平台 <a class="header-anchor" href="#第-1-步-选平台" aria-label="Permalink to &quot;第 1 步：选平台&quot;">​</a></h3><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><code>qq_official</code></td><td>QQ 官方开放平台机器人，支持 Webhook 回调与 WebSocket 网关两种连接方式</td></tr><tr><td><code>qq_onebot</code></td><td>通过 NapCat / go-cqhttp 等实现端接入的 OneBot 11，只支持反向 WebSocket</td></tr></tbody></table><p>选哪个见 <a href="/RuaBot.Doc/platforms/overview">接入方式总览</a>。</p><h3 id="第-2-步-填名称与平台配置-并选连接方式" tabindex="-1">第 2 步：填名称与平台配置，并选连接方式 <a class="header-anchor" href="#第-2-步-填名称与平台配置-并选连接方式" aria-label="Permalink to &quot;第 2 步：填名称与平台配置，并选连接方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>只用于你在控制台里区分机器人，不影响机器人本身</td></tr><tr><td>平台配置</td><td>随第 1 步的平台变化：<code>qq_official</code> 要 <code>AppID</code> / <code>AppSecret</code> / 环境；<code>qq_onebot</code> 无需额外凭据</td></tr><tr><td>连接方式</td><td><code>qq_official</code> 可选 WebSocket 网关或 Webhook 回调；<code>qq_onebot</code> 固定为反向 WebSocket</td></tr></tbody></table><p>提交后机器人<strong>立即上线，不需要重启服务</strong>。如果你选的是 Webhook 或 OneBot，创建完成后页面上会给出需要回填到平台 / 实现端的地址，照着填即可。</p><div class="tip custom-block"><p class="custom-block-title">建之前先确认额度</p><p>机器人数受套餐限制。额度不够时添加会被拒绝，需要先升级套餐或删掉不用的机器人，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>。</p></div><h2 id="_2-机器人列表" tabindex="-1">2. 机器人列表 <a class="header-anchor" href="#_2-机器人列表" aria-label="Permalink to &quot;2. 机器人列表&quot;">​</a></h2><p>列表里每行是一台机器人，你主要关注这几列：</p><table tabindex="0"><thead><tr><th>列</th><th>看什么</th></tr></thead><tbody><tr><td>名称</td><td>你创建时起的名字</td></tr><tr><td>适配器</td><td><code>qq_official</code> 或 <code>qq_onebot</code></td></tr><tr><td>连接方式</td><td>WebSocket 网关 / Webhook 回调 / 反向 WebSocket</td></tr><tr><td>状态</td><td>在线还是离线</td></tr><tr><td>操作</td><td>进入详情、删除等</td></tr></tbody></table><p><strong>判断机器人是否在线</strong>，直接看列表的状态列即可；进详情页的「设置」Tab 也能看到同样的状态，以及更细的信息。</p><h2 id="_3-机器人详情页的五个-tab" tabindex="-1">3. 机器人详情页的五个 Tab <a class="header-anchor" href="#_3-机器人详情页的五个-tab" aria-label="Permalink to &quot;3. 机器人详情页的五个 Tab&quot;">​</a></h2><p>点进一台机器人，顶部有五个 Tab。</p><h3 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h3><p>这台机器人当前装了哪些插件，以及每项的操作：</p><ul><li><strong>启用 / 停用</strong>：单独控制某个插件在这台机器人上跑不跑</li><li><strong>优先级</strong>：调整插件的执行顺序，值越小越先执行</li><li><strong>三个拦截开关</strong>：控制这个插件的拦截能力在这台机器人上生不生效 <ul><li><code>Incoming 拦截</code>：消息进来时先过一遍这个插件（可以改写甚至拦下消息）</li><li><code>Outgoing 拦截</code>：机器人要发出去的消息先过一遍这个插件（可以改写或阻止发送）</li><li><code>AfterSend 回调</code>：消息发出后通知这个插件（用来记录发送结果、做后续动作）</li></ul></li><li><strong>进入插件面板</strong>：打开插件自带的 Web 面板，做这个插件在这台机器人上的配置</li></ul><p>注意插件配置是<strong>按机器人维度</strong>存的：同一插件装到两台机器人上，是两份独立配置。</p><h3 id="事件转发" tabindex="-1">事件转发 <a class="header-anchor" href="#事件转发" aria-label="Permalink to &quot;事件转发&quot;">​</a></h3><p><strong>只有 Webhook 模式接入的机器人才能看到这个 Tab。</strong> 用它查看和配置事件往哪里转发。</p><p>如果你用的是 WebSocket 网关或 OneBot，看不到这个 Tab 是正常的，说明该模式不需要它。</p><h3 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h3><p>这台机器人的运行数据：</p><ul><li>消息记录：群里收发的消息流水</li><li>插件数据：插件自己存下来的数据</li></ul><p>排障时「群里到底有没有收到消息」在这里最直观。</p><h3 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h3><p><strong>这台机器人自己的运行日志</strong>，不用登服务器、不用翻整个服务的日志。连接断开、事件处理报错这类问题都在这里看。</p><h3 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h3><p>机器人的身份与状态信息：</p><table tabindex="0"><thead><tr><th>显示项</th><th>说明</th></tr></thead><tbody><tr><td>UUID</td><td>这台机器人在控制台里的唯一标识</td></tr><tr><td>适配器</td><td><code>qq_official</code> 或 <code>qq_onebot</code></td></tr><tr><td>连接方式</td><td>当前用的连接方式</td></tr><tr><td>状态</td><td>在线 / 离线</td></tr><tr><td>支持能力列表</td><td>这台机器人当前支持的能力，写插件调用能力码时可以对照</td></tr></tbody></table><p>机器人详情页的排障入口基本就是这三个：<strong>设置看状态、日志看原因、数据验证消息有没有进来</strong>。</p><details class="details custom-block"><summary>截图占位</summary><p>截两张：一是两步向导的第二步（露出名称、平台配置、连接方式三块）；二是详情页顶部 Tab 栏，把五个 Tab 名称都露出来。</p></details><h2 id="_4-让机器人进群" tabindex="-1">4. 让机器人进群 <a class="header-anchor" href="#_4-让机器人进群" aria-label="Permalink to &quot;4. 让机器人进群&quot;">​</a></h2><p>机器人本身不会自动进群，需要你手动把它拉进去：</p><ul><li><strong>QQ 官方机器人</strong>：在 QQ 开放平台把机器人配置好之后，用群管理操作把它拉进目标群。默认它只在被 @ 时收到消息；要收全量消息需要「群全量消息」授权，见 <a href="/RuaBot.Doc/platforms/qq-official">QQ 官方：WebSocket 网关</a>。</li><li><strong>OneBot 11</strong>：机器人就是你自己登录的那个 QQ 号，用这个号正常加群即可，见 <a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a>。</li></ul><p>拉进群之后，在群里发条消息，回到详情页「数据」Tab 确认消息进来了。</p><h2 id="_5-常见问题" tabindex="-1">5. 常见问题 <a class="header-anchor" href="#_5-常见问题" aria-label="Permalink to &quot;5. 常见问题&quot;">​</a></h2><h3 id="症状-新建的机器人一直离线" tabindex="-1">症状：新建的机器人一直离线 <a class="header-anchor" href="#症状-新建的机器人一直离线" aria-label="Permalink to &quot;症状：新建的机器人一直离线&quot;">​</a></h3><ul><li><strong>原因</strong>：凭据填错、实现端没连上，或端口 / 地址填错。</li><li><strong>处理方式</strong>：按适配器分别排查——QQ 官方看 <a href="/RuaBot.Doc/platforms/qq-official">WebSocket 网关</a> 的排错清单，OneBot 看 <a href="/RuaBot.Doc/platforms/qq-onebot">QQ OneBot 11</a> 的排错清单。</li></ul><h3 id="症状-机器人删掉了-但额度没释放" tabindex="-1">症状：机器人删掉了，但额度没释放 <a class="header-anchor" href="#症状-机器人删掉了-但额度没释放" aria-label="Permalink to &quot;症状：机器人删掉了，但额度没释放&quot;">​</a></h3><ul><li><strong>原因</strong>：页面缓存未刷新。</li><li><strong>处理方式</strong>：刷新页面再看订阅中心的额度显示。</li></ul><h3 id="症状-装了插件但机器人没反应" tabindex="-1">症状：装了插件但机器人没反应 <a class="header-anchor" href="#症状-装了插件但机器人没反应" aria-label="Permalink to &quot;症状：装了插件但机器人没反应&quot;">​</a></h3><ul><li><strong>原因</strong>：插件只是装上了，没有<strong>启用</strong>。</li><li><strong>处理方式</strong>：到「插件」Tab 确认该插件处于启用状态，且处于启用优先级链里。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/plugins">插件市场与安装</a></li><li><a href="/RuaBot.Doc/platforms/overview">接入方式总览</a></li><li><a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a></li></ul>',49)])])}const u=a(d,[["render",l]]);export{p as __pageData,u as default};
